        // Creates a complete ZIP in the reports folder (Data\Reports) with all the logs and system info.
        // ══════════════════════════════════════════════════════════════════════
        private void BtnExportDiag_Click(object sender, System.Windows.RoutedEventArgs e)
        {
            var win = new DiagPackageWindow(ExportDiagPackageAsync);
            win.Owner = this;
            win.ShowDialog();
        }

