                                if (!System.IO.Directory.Exists(srcFolder)) return;
                                var files = System.IO.Directory.GetFiles(srcFolder, "*", System.IO.SearchOption.TopDirectoryOnly)
                                    .Select(f => new System.IO.FileInfo(f))
                                    .OrderByDescending(fi => fi.LastWriteTimeUtc)
