                            CopyLastFiles(@"C:\Windows\Logs\NetSetup", "NetSetupLogs");
                            CopyLastFiles(@"C:\Windows\Logs\SIH",      "SIH");
                            CopyLastFiles(@"C:\Windows\Logs\WindowsUpdate", "WU");
                            // WindowsUpdate.log note
                            System.IO.File.WriteAllText(
                                System.IO.Path.Combine(winLogsDir, "WindowsUpdate_note.txt"),
                                "To get WindowsUpdate.log run in PowerShell (Admin):\n" +
                                "Get-WindowsUpdateLog -LogPath $env:TEMP\\WindowsUpdate.log\n");
                        }

                        catch (Exception ex) { AppLogger.Debug(ex.Message); }
                        }  // end Inc("winlogs")

                        // ── 9. smdwin_logs/ ───────────────────────────────────
if (Inc("smdlogs"))
                        {
                                                try
                        {
                            string appLogDir = SMDWin.Services.AppLogger.LogDirectory;
                            string destLogDir = System.IO.Path.Combine(tmpDir, "smdwin_logs");
                            System.IO.Directory.CreateDirectory(destLogDir);
                            if (System.IO.Directory.Exists(appLogDir))
                            {
                                var files = System.IO.Directory.GetFiles(appLogDir, "*.log")
                                    .Concat(System.IO.Directory.GetFiles(appLogDir, "*.csv"))
                                    .OrderByDescending(f => System.IO.File.GetLastWriteTime(f))
                                    .Take(10);
                                foreach (var f in files)
                                {
                                    string dest = System.IO.Path.Combine(
                                        destLogDir, System.IO.Path.GetFileName(f));
                                    try
                                    {
                                        using var src = new System.IO.FileStream(f,
                                            System.IO.FileMode.Open, System.IO.FileAccess.Read,
                                            System.IO.FileShare.ReadWrite);
                                        using var dst = System.IO.File.Create(dest);
                                        src.CopyTo(dst);
                                    }
                                    catch (Exception ex) { AppLogger.Debug(ex.Message); }
                                }
                            }
                        }

                        catch (Exception ex) { AppLogger.Debug(ex.Message); }
                        }  // end Inc("smdlogs")

                        // ── 10. system_info_summary.txt ───────────────────────
                        try
                        {
                            var sb = new System.Text.StringBuilder();
                            sb.AppendLine("=== System Summary + Installed Applications ===");
                            sb.AppendLine($"Generated: {DateTime.Now:yyyy-MM-dd HH:mm:ss}");
                            sb.AppendLine();
                            using var csSearcher = SMDWin.Services.WmiHelper.Searcher(
                                "SELECT * FROM Win32_ComputerSystem", System.TimeSpan.FromSeconds(10));
                            using (var __wmiTmp9 = csSearcher.Get())
                            {
                                foreach (System.Management.ManagementObject obj in __wmiTmp9)
                            {
                                sb.AppendLine($"Manufacturer:     {obj["Manufacturer"]}");
                                sb.AppendLine($"Model:            {obj["Model"]}");
                                sb.AppendLine($"Total RAM:        {Convert.ToUInt64(obj["TotalPhysicalMemory"]) / (1024 * 1024 * 1024)} GB");
                                sb.AppendLine($"System type:      {obj["SystemType"]}");
                                sb.AppendLine($"Domain/Workgroup: {obj["Domain"]}");
                            }
                            }
                            sb.AppendLine();
                            sb.AppendLine("── Installed Programs ─────────────────────────");
                            int appCount = 0;
                            foreach (var regPath in new[]
                            {
                                @"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall",
                                @"SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall",
                            })
                            {
                                try
                                {
                                    using var key = Microsoft.Win32.Registry.LocalMachine.OpenSubKey(regPath);
                                    if (key == null) continue;
                                    foreach (var sub in key.GetSubKeyNames())
                                    {
                                        using var app = key.OpenSubKey(sub);
                                        string? name = app?.GetValue("DisplayName")?.ToString();
                                        string? ver  = app?.GetValue("DisplayVersion")?.ToString() ?? "";
                                        string? date = app?.GetValue("InstallDate")?.ToString() ?? "";
                                        if (!string.IsNullOrWhiteSpace(name))
                                        {
                                            sb.AppendLine($"  {name,-60} {ver,-20} {date}");
                                            appCount++;
                                        }
                                    }
                                }
                                catch (Exception ex) { AppLogger.Debug(ex.Message); }
                            }
                            sb.AppendLine($"  Total: {appCount} applications");
                            System.IO.File.WriteAllText(
                                System.IO.Path.Combine(tmpDir, "system_info_summary.txt"), sb.ToString());
                        }
                        catch (Exception ex)
                        {
                            System.IO.File.WriteAllText(
                                System.IO.Path.Combine(tmpDir, "system_info_summary.txt"),
                                $"Error: {ex.Message}");
                        }

                        if (Inc("reliability"))
                        try
                        {
                            var sb = new System.Text.StringBuilder();
                            sb.AppendLine("=== Reliability Monitor (Win32_ReliabilityRecords) ===");
                            sb.AppendLine("Same source as perfmon /rel — app crashes, Windows Updates,");
                            sb.AppendLine("driver installs, hardware errors, unexpected shutdowns.");
                            sb.AppendLine();
                            using var relSearcher = SMDWin.Services.WmiHelper.Searcher(
                                "SELECT * FROM Win32_ReliabilityRecords", System.TimeSpan.FromSeconds(10));
                            int relCount = 0;
                            var relRecords = new List<(DateTime time, string text)>();
                            using (var __wmiTmp10 = relSearcher.Get())
                            {
                                foreach (System.Management.ManagementObject obj in __wmiTmp10)
                            {
                                try
                                {
                                    string wmiTime = obj["TimeGenerated"]?.ToString() ?? "";
                                    DateTime dt = !string.IsNullOrEmpty(wmiTime)
                                        ? System.Management.ManagementDateTimeConverter.ToDateTime(wmiTime)
                                        : DateTime.MinValue;
                                    string src = obj["SourceName"]?.ToString() ?? "?";
                                    string prod = obj["ProductName"]?.ToString() ?? "";
                                    string msg = obj["Message"]?.ToString() ?? "";
                                    msg = msg.Replace("\r\n", " ").Replace("\n", " ").Trim();
                                    if (msg.Length > 300) msg = msg[..300] + "…";
                                    relRecords.Add((dt, $"[{dt:yyyy-MM-dd HH:mm:ss}] {src,-28} {prod,-24} {msg}"));
                                    relCount++;
                                }
                                catch (Exception ex) { AppLogger.Debug(ex.Message); }
                            }
                            }
                            foreach (var r in relRecords.OrderByDescending(r => r.time).Take(500))
                                sb.AppendLine(r.text);
                            sb.AppendLine();
                            sb.AppendLine($"→ {relCount} total reliability records (showing up to 500, newest first)");
                            System.IO.File.WriteAllText(
                                System.IO.Path.Combine(tmpDir, "reliability_monitor.txt"), sb.ToString());
                        }
                        catch (Exception ex)
                        {
                            System.IO.File.WriteAllText(
                                System.IO.Path.Combine(tmpDir, "reliability_monitor.txt"), $"Error: {ex.Message}");
                        }

                        if (Inc("criticalevents"))
                        try
                        {
                            var sb = new System.Text.StringBuilder();
                            sb.AppendLine("=== Critical Event Providers — ALL entries, last 90 days ===");
                            sb.AppendLine("Raw, unfiltered by level — includes Informational (e.g. corrected WHEA errors).");
                            sb.AppendLine();
                            string cutoff90 = DateTime.UtcNow.AddDays(-90).ToString("yyyy-MM-ddTHH:mm:ssZ");

                            void DumpGroup(string groupLabel, string logName, string[] providers, int[]? eventIds = null)
                            {
                                sb.AppendLine($"─── {groupLabel} ({logName} log) ────────────────────");
                                try
                                {
                                    string providerXPath = string.Join(" or ", providers.Select(p => $"Provider[@Name='{p}']"));
                                    string idXPath = eventIds != null
                                        ? " and (" + string.Join(" or ", eventIds.Select(id => $"EventID={id}")) + ")"
                                        : "";
                                    string xpath = $"*[System[({providerXPath}){idXPath} and TimeCreated[@SystemTime>='{cutoff90}']]]";
                                    using var reader = new System.Diagnostics.Eventing.Reader.EventLogReader(
                                        new System.Diagnostics.Eventing.Reader.EventLogQuery(logName,
                                            System.Diagnostics.Eventing.Reader.PathType.LogName, xpath));
                                    int count = 0;
                                    System.Diagnostics.Eventing.Reader.EventRecord? rec;
                                    while ((rec = reader.ReadEvent()) != null && count < 500)
                                    {
                                        using (rec)
                                        {
                                            count++;
                                            string lvl = rec.Level switch { 1 => "CRIT", 2 => "ERR ", 3 => "WARN", 4 => "INFO", _ => "?   " };
                                            string ts = rec.TimeCreated?.ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss") ?? "?";
                                            string src = (rec.ProviderName ?? "?").PadRight(36);
                                            string msg = "";
                                            try { msg = rec.FormatDescription() ?? ""; } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                                            msg = msg.Replace("\r\n", " ").Replace("\n", " ").Trim();
                                            if (msg.Length > 400) msg = msg[..400] + "…";
                                            sb.AppendLine($"[{lvl}] {ts}  ID:{rec.Id,-6} {src} {msg}");
                                        }
                                    }
                                    sb.AppendLine(count == 0 ? "  (none found)" : $"  → {count} events");
                                }
                                catch (Exception ex) { sb.AppendLine($"  Error: {ex.Message}"); }
                                sb.AppendLine();
                            }

                            DumpGroup("WHEA (hardware errors)", "System", new[] { "Microsoft-Windows-WHEA-Logger" });
                            DumpGroup("Kernel-Power (unexpected shutdown, ID 41 only — see below for sleep/wake count)", "System",
                                new[] { "Microsoft-Windows-Kernel-Power" }, new[] { 41 });
                            sb.AppendLine("─── Kernel-Power — sleep/wake volume (informational, not dumped) ──");
                            try
                            {
                                string sleepWakeXPath = $"*[System[(Provider[@Name='Microsoft-Windows-Kernel-Power']) and (EventID=42 or EventID=107) and TimeCreated[@SystemTime>='{cutoff90}']]]";
                                using var swReader = new System.Diagnostics.Eventing.Reader.EventLogReader(
                                    new System.Diagnostics.Eventing.Reader.EventLogQuery("System",
                                        System.Diagnostics.Eventing.Reader.PathType.LogName, sleepWakeXPath));
                                int swCount = 0;
                                while (swReader.ReadEvent() is { } swRec && swCount < 5000) { using (swRec) swCount++; }
                                sb.AppendLine($"  → {swCount} normal sleep/wake transitions in the last 90 days (ID 42/107) — not a problem, shown only for context.");
                            }
                            catch (Exception ex) { sb.AppendLine($"  Error: {ex.Message}"); }
                            sb.AppendLine();
                            DumpGroup("BugCheck (via WER-SystemErrorReporting)", "System", new[] { "Microsoft-Windows-WER-SystemErrorReporting" });
                            DumpGroup("Disk / NTFS / Storage controllers", "System",
                                new[] { "disk", "Ntfs", "storahci", "stornvme", "iaStorAC", "iaStorAVC", "nvme" });
                            DumpGroup("Display drivers (NVIDIA/AMD/Intel)", "System",
                                new[] { "nvlddmkm", "amdkmdag", "igfx", "Display" });
                            DumpGroup("USB", "System", new[] { "usbhub3", "USB", "Microsoft-Windows-USB-USBHUB3" });
                            DumpGroup("WLAN", "System", new[] { "Microsoft-Windows-WLAN-AutoConfig" });
                            DumpGroup("Service Control Manager", "System", new[] { "Service Control Manager" });
                            DumpGroup("DriverFrameworks-UserMode", "System", new[] { "Microsoft-Windows-DriverFrameworks-UserMode" });

                            System.IO.File.WriteAllText(
                                System.IO.Path.Combine(tmpDir, "critical_event_providers.txt"), sb.ToString());
                        }
                        catch (Exception ex)
                        {
                            System.IO.File.WriteAllText(
                                System.IO.Path.Combine(tmpDir, "critical_event_providers.txt"), $"Error: {ex.Message}");
                        }

                        if (Inc("werreports"))
                        try
                        {
                            var sb = new System.Text.StringBuilder();
                            sb.AppendLine("=== Windows Error Reporting (WER) — recent reports ===");
                            sb.AppendLine();
                            int werCount = 0;
                            foreach (var werFolder in new[]
                            {
                                @"C:\ProgramData\Microsoft\Windows\WER\ReportArchive",
                                @"C:\ProgramData\Microsoft\Windows\WER\ReportQueue",
                            })
                            {
                                if (!System.IO.Directory.Exists(werFolder)) continue;
                                var reportDirs = System.IO.Directory.GetDirectories(werFolder)
                                    .Select(d => new System.IO.DirectoryInfo(d))
                                    .OrderByDescending(d => d.LastWriteTimeUtc)
                                    .Take(30);
                                foreach (var rd in reportDirs)
                                {
                                    string werFile = System.IO.Path.Combine(rd.FullName, "Report.wer");
                                    if (!System.IO.File.Exists(werFile)) continue;
                                    try
                                    {
                                        sb.AppendLine($"─── {rd.Name} ({rd.LastWriteTime:yyyy-MM-dd HH:mm:ss}) ───");
                                        // Report.wer is UTF-16 text, ini format — small content (a few KB), included in full.
                                        string content = System.IO.File.ReadAllText(werFile, System.Text.Encoding.Unicode);
                                        sb.AppendLine(content.Trim());
                                        sb.AppendLine();
                                        werCount++;
                                    }
                                    catch (Exception ex) { sb.AppendLine($"  (could not read: {ex.Message})"); }
                                }
                            }
                            sb.AppendLine($"→ {werCount} WER reports included (up to 30 most recent per folder)");
                            System.IO.File.WriteAllText(
                                System.IO.Path.Combine(tmpDir, "wer_reports.txt"), sb.ToString());
                        }
                        catch (Exception ex)
                        {
                            System.IO.File.WriteAllText(
                                System.IO.Path.Combine(tmpDir, "wer_reports.txt"), $"Error: {ex.Message}");
                        }

                        if (Inc("livekernel"))
                        try
                        {
                            var sb = new System.Text.StringBuilder();
                            sb.AppendLine("=== LiveKernelReports — file listing (non-fatal kernel events) ===");
                            sb.AppendLine("Folder name = event category. Cannot parse .dmp contents without WinDbg —");
                            sb.AppendLine("this is a listing (what happened + when), not full analysis.");
                            sb.AppendLine();
                            string lkrPath = @"C:\Windows\LiveKernelReports";
                            int lkrCount = 0;
                            if (System.IO.Directory.Exists(lkrPath))
                            {
                                foreach (var sub in System.IO.Directory.GetDirectories(lkrPath))
                                {
                                    var files = System.IO.Directory.GetFiles(sub, "*", System.IO.SearchOption.TopDirectoryOnly)
                                        .Select(f => new System.IO.FileInfo(f))
                                        .OrderByDescending(fi => fi.LastWriteTimeUtc)
                                        .ToList();
                                    if (files.Count == 0) continue;
                                    sb.AppendLine($"─── {System.IO.Path.GetFileName(sub)} ───");
                                    foreach (var fi in files.Take(20))
                                    {
                                        sb.AppendLine($"  {fi.LastWriteTime:yyyy-MM-dd HH:mm:ss}  {fi.Name}  ({fi.Length / 1024} KB)");
                                        lkrCount++;
                                    }
                                    sb.AppendLine();
                                }
                            }
                            sb.AppendLine(lkrCount == 0 ? "→ No LiveKernelReports found (good sign — no non-fatal kernel events recorded)."
                                                          : $"→ {lkrCount} files listed across all categories.");
                            System.IO.File.WriteAllText(
                                System.IO.Path.Combine(tmpDir, "live_kernel_reports.txt"), sb.ToString());
                        }
                        catch (Exception ex)
                        {
                            System.IO.File.WriteAllText(
                                System.IO.Path.Combine(tmpDir, "live_kernel_reports.txt"), $"Error: {ex.Message}");
                        }

                        if (Inc("rawcmds"))
                        try
                        {
                            var sb = new System.Text.StringBuilder();
                            sb.AppendLine("=== Raw Diagnostic Commands (unedited output) ===");
                            sb.AppendLine($"Generated: {DateTime.Now:yyyy-MM-dd HH:mm:ss}");
                            sb.AppendLine();

                            string RunCapture(string exe, string args, int timeoutMs)
                            {
                                try
                                {
                                    var psi = new System.Diagnostics.ProcessStartInfo(exe, args)
                                    {
                                        CreateNoWindow = true, UseShellExecute = false,
                                        RedirectStandardOutput = true, RedirectStandardError = true,
                                    };
                                    using var p = System.Diagnostics.Process.Start(psi);
                                    if (p == null) return "(could not start process)";
                                    string? outp = SMDWin.Services.ProcessRunner.ReadStdoutBounded(p, timeoutMs);
                                    if (outp == null) return "(timed out)";
                                    if (!p.WaitForExit(timeoutMs)) { try { p.Kill(entireProcessTree: true); } catch (System.Exception __ignored) { SMDWin.Services.AppLogger.Swallowed(__ignored); } return "(timed out)"; }
                                    return outp;
                                }
                                catch (Exception ex) { return $"(error: {ex.Message})"; }
                            }

                            void Section(string title, string exe, string args, int timeoutMs = 15000)
                            {
                                sb.AppendLine($"═══ {title} ═══════════════════════════════════");
                                sb.AppendLine(RunCapture(exe, args, timeoutMs).TrimEnd());
                                sb.AppendLine();
                            }

                            Section("systeminfo", "systeminfo", "");
                            Section("driverquery /v", "driverquery", "/v /fo list");
                            Section("pnputil /enum-devices /problem", "pnputil", "/enum-devices /problem");
                            Section("bcdedit /enum all", "bcdedit", "/enum all");
                            Section("fltmc filters", "fltmc", "filters");
                            Section("wmic cpu", "wmic", "cpu get Name,MaxClockSpeed,NumberOfCores,NumberOfLogicalProcessors /format:list");
                            Section("wmic baseboard", "wmic", "baseboard get Manufacturer,Product,SerialNumber /format:list");
                            Section("wmic bios", "wmic", "bios get Manufacturer,Name,SMBIOSBIOSVersion,ReleaseDate /format:list");
                            Section("wmic memorychip", "wmic", "memorychip get Manufacturer,Capacity,Speed,DeviceLocator /format:list");
                            Section("wmic pagefile", "wmic", "pagefile get Name,AllocatedBaseSize,CurrentUsage /format:list");
                            // msinfo32 and dxdiag write directly to a file (not to stdout) — a different pattern, handled separately below.
                            try
                            {
                                string msinfoPath = System.IO.Path.Combine(tmpDir, "msinfo32_report.txt");
                                var psiMs = new System.Diagnostics.ProcessStartInfo("msinfo32", $"/report \"{msinfoPath}\"")
                                { CreateNoWindow = true, UseShellExecute = false };
                                using var pMs = System.Diagnostics.Process.Start(psiMs);
                                pMs?.WaitForExit(60000);
                                sb.AppendLine("═══ msinfo32 /report ═══════════════════════════════");
                                sb.AppendLine(System.IO.File.Exists(msinfoPath)
                                    ? "→ saved separately as msinfo32_report.txt (too large to inline here)"
                                    : "→ msinfo32 did not produce a report (timed out or unavailable)");
                                sb.AppendLine();
                            }
                            catch (Exception ex) { sb.AppendLine($"═══ msinfo32 /report ═══════════════════════════════\n(error: {ex.Message})\n"); }
                            try
                            {
                                string dxdiagPath = System.IO.Path.Combine(tmpDir, "dxdiag_report.txt");
                                var psiDx = new System.Diagnostics.ProcessStartInfo("dxdiag", $"/t \"{dxdiagPath}\"")
                                { CreateNoWindow = true, UseShellExecute = false };
                                using var pDx = System.Diagnostics.Process.Start(psiDx);
                                pDx?.WaitForExit(30000);
                                sb.AppendLine("═══ dxdiag /t ═══════════════════════════════════════");
                                sb.AppendLine(System.IO.File.Exists(dxdiagPath)
                                    ? "→ saved separately as dxdiag_report.txt (too large to inline here)"
                                    : "→ dxdiag did not produce a report (timed out or unavailable)");
                            }
                            catch (Exception ex) { sb.AppendLine($"═══ dxdiag /t ═══════════════════════════════════════\n(error: {ex.Message})"); }

                            System.IO.File.WriteAllText(
                                System.IO.Path.Combine(tmpDir, "raw_commands.txt"), sb.ToString());
                        }
                        catch (Exception ex)
                        {
                            System.IO.File.WriteAllText(
                                System.IO.Path.Combine(tmpDir, "raw_commands.txt"), $"Error: {ex.Message}");
                        }
                    }); // end Task.Run

                    // ── ZIP ────────────────────────────────────────────────────
                    if (System.IO.File.Exists(zipPath)) System.IO.File.Delete(zipPath);
                    System.IO.Compression.ZipFile.CreateFromDirectory(tmpDir, zipPath);
                }
                finally
                {
                    try { System.IO.Directory.Delete(tmpDir, recursive: true); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                }

                long sizeMb = new System.IO.FileInfo(zipPath).Length / (1024 * 1024);
                SMDWin.Services.ToolActivityLog.Add("Diagnostic package", $"{zipName} · {Math.Max(1, sizeMb)} MB in {System.IO.Path.GetDirectoryName(zipPath)}", "ok");
                _ = Dispatcher.InvokeAsync(() =>
                    ShowToastSuccess(string.Format(LanguageService.S("Msg", "DiagSavedFmt"), sizeMb), 6000));
            }
            catch (Exception ex)
            {
                SMDWin.Services.ToolActivityLog.Add("Diagnostic package", "export failed", "warn");
                _ = Dispatcher.InvokeAsync(() => ShowToastError(string.Format(LanguageService.S("Msg", "ExportFailedFmt"), ex.Message)));
            }
        }
    }
}
